CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('STUDENT','PARENT','ADMIN')), grade integer NOT NULL DEFAULT 7 CHECK (grade IN(7,8)), daily_minutes integer NOT NULL DEFAULT 30 CHECK(daily_minutes IN(20,30,45,60)), preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY, user_id uuid REFERENCES users ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS password_resets (id uuid PRIMARY KEY,user_id uuid REFERENCES users ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,used boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_events (id uuid PRIMARY KEY,identifier text NOT NULL,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS auth_events_identifier ON auth_events(identifier,created_at);
CREATE TABLE IF NOT EXISTS student_profiles (user_id uuid PRIMARY KEY REFERENCES users ON DELETE CASCADE,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS parent_profiles (user_id uuid PRIMARY KEY REFERENCES users ON DELETE CASCADE,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS parent_student_links (parent_id uuid REFERENCES users ON DELETE CASCADE,student_id uuid REFERENCES users ON DELETE CASCADE,PRIMARY KEY(parent_id,student_id));
CREATE TABLE IF NOT EXISTS academic_years (id uuid PRIMARY KEY,title text UNIQUE NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS grades (id uuid PRIMARY KEY,number integer UNIQUE NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS curriculum_sources (id uuid PRIMARY KEY,url text UNIQUE NOT NULL,title text NOT NULL,version text NOT NULL,verified_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS curriculum_nodes (id uuid PRIMARY KEY,parent_id uuid REFERENCES curriculum_nodes ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN('subject','unit','topic','subtopic','outcome','skill','content')),title text NOT NULL,grade integer NOT NULL CHECK(grade IN(7,8)),subject text NOT NULL,code text,source_url text,academic_year text NOT NULL DEFAULT '2026-2027',curriculum_version text NOT NULL DEFAULT 'DRAFT',verified boolean NOT NULL DEFAULT false,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS curriculum_parent ON curriculum_nodes(parent_id,grade);
CREATE TABLE IF NOT EXISTS questions (id uuid PRIMARY KEY,topic_id uuid REFERENCES curriculum_nodes ON DELETE CASCADE,kind text NOT NULL,prompt text NOT NULL,options jsonb,answer text NOT NULL,explanation text NOT NULL,difficulty text NOT NULL CHECK(difficulty IN('easy','medium','hard')),passage text,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','validated','approved','rejected')),origin text NOT NULL DEFAULT 'original',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS question_bank ON questions(topic_id,status,difficulty);
CREATE TABLE IF NOT EXISTS question_options (id uuid PRIMARY KEY,question_id uuid REFERENCES questions ON DELETE CASCADE,position integer NOT NULL,text text NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS question_validations (id uuid PRIMARY KEY,question_id uuid REFERENCES questions ON DELETE CASCADE,valid boolean NOT NULL,report jsonb NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS tests (id uuid PRIMARY KEY,student_id uuid REFERENCES users ON DELETE CASCADE,title text NOT NULL,topic_id uuid REFERENCES curriculum_nodes ON DELETE CASCADE,mode text NOT NULL DEFAULT 'practice',time_limit integer,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS test_questions (test_id uuid REFERENCES tests ON DELETE CASCADE,question_id uuid REFERENCES questions ON DELETE CASCADE,position integer NOT NULL,PRIMARY KEY(test_id,question_id));
CREATE TABLE IF NOT EXISTS test_sessions (id uuid PRIMARY KEY,test_id uuid REFERENCES tests ON DELETE CASCADE,student_id uuid REFERENCES users ON DELETE CASCADE,started_at timestamptz DEFAULT now(),completed_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS question_attempts (id uuid PRIMARY KEY,test_id uuid REFERENCES tests ON DELETE CASCADE,question_id uuid REFERENCES questions ON DELETE CASCADE,student_id uuid REFERENCES users ON DELETE CASCADE,answer text,correct boolean NOT NULL,skipped boolean NOT NULL DEFAULT false,help_level integer NOT NULL DEFAULT 0 CHECK(help_level BETWEEN 0 AND 5),response_ms integer NOT NULL CHECK(response_ms>=0),error_type text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(test_id,question_id,student_id));
CREATE INDEX IF NOT EXISTS attempts_student ON question_attempts(student_id,created_at);
CREATE TABLE IF NOT EXISTS student_topic_mastery (student_id uuid REFERENCES users ON DELETE CASCADE,topic_id uuid REFERENCES curriculum_nodes ON DELETE CASCADE,score numeric NOT NULL DEFAULT 0,attempt_count integer NOT NULL DEFAULT 0,updated_at timestamptz DEFAULT now(),created_at timestamptz DEFAULT now(),PRIMARY KEY(student_id,topic_id));
CREATE TABLE IF NOT EXISTS student_error_patterns (student_id uuid REFERENCES users ON DELETE CASCADE,topic_id uuid REFERENCES curriculum_nodes ON DELETE CASCADE,error_type text NOT NULL,count integer NOT NULL DEFAULT 1,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),PRIMARY KEY(student_id,topic_id,error_type));
CREATE TABLE IF NOT EXISTS review_queue (student_id uuid REFERENCES users ON DELETE CASCADE,topic_id uuid REFERENCES curriculum_nodes ON DELETE CASCADE,interval_index integer NOT NULL DEFAULT 0,due_at timestamptz NOT NULL,last_review_at timestamptz,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),PRIMARY KEY(student_id,topic_id));
CREATE TABLE IF NOT EXISTS study_sessions (id uuid PRIMARY KEY,student_id uuid REFERENCES users ON DELETE CASCADE,test_id uuid REFERENCES tests ON DELETE CASCADE,duration_ms integer NOT NULL DEFAULT 0,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS study_plans (id uuid PRIMARY KEY,student_id uuid REFERENCES users ON DELETE CASCADE,day date NOT NULL,minutes integer NOT NULL,items jsonb NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(student_id,day));
CREATE TABLE IF NOT EXISTS homeworks (id uuid PRIMARY KEY,student_id uuid REFERENCES users ON DELETE CASCADE,subject text NOT NULL,title text NOT NULL,due_at date NOT NULL,completed boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS exams (id uuid PRIMARY KEY,student_id uuid REFERENCES users ON DELETE CASCADE,subject text NOT NULL,title text NOT NULL,due_at date NOT NULL,topic_ids jsonb NOT NULL DEFAULT '[]',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS badges (id uuid PRIMARY KEY,code text UNIQUE NOT NULL,title text NOT NULL,threshold integer NOT NULL,kind text NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS student_badges (student_id uuid REFERENCES users ON DELETE CASCADE,badge_id uuid REFERENCES badges ON DELETE CASCADE,earned_at timestamptz DEFAULT now(),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),PRIMARY KEY(student_id,badge_id));
CREATE TABLE IF NOT EXISTS streaks (student_id uuid PRIMARY KEY REFERENCES users ON DELETE CASCADE,current_days integer NOT NULL DEFAULT 0,best_days integer NOT NULL DEFAULT 0,last_day date,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_conversations (id uuid PRIMARY KEY,student_id uuid REFERENCES users ON DELETE CASCADE,topic_id uuid REFERENCES curriculum_nodes ON DELETE SET NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_messages (id uuid PRIMARY KEY,conversation_id uuid REFERENCES ai_conversations ON DELETE CASCADE,role text NOT NULL,content text NOT NULL,help_level integer NOT NULL DEFAULT 0,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_usage (id uuid PRIMARY KEY,user_id uuid REFERENCES users ON DELETE CASCADE,feature text NOT NULL,model text NOT NULL,input_tokens integer NOT NULL,output_tokens integer NOT NULL,estimated_cost numeric,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY,user_id uuid REFERENCES users ON DELETE CASCADE,message text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE OR REPLACE VIEW subjects AS SELECT * FROM curriculum_nodes WHERE kind='subject';
CREATE OR REPLACE VIEW units AS SELECT * FROM curriculum_nodes WHERE kind='unit';
CREATE OR REPLACE VIEW topics AS SELECT * FROM curriculum_nodes WHERE kind='topic';
CREATE OR REPLACE VIEW subtopics AS SELECT * FROM curriculum_nodes WHERE kind='subtopic';
CREATE OR REPLACE VIEW learning_outcomes AS SELECT * FROM curriculum_nodes WHERE kind='outcome';

ALTER TABLE ai_conversations ADD COLUMN IF NOT EXISTS question_id uuid REFERENCES questions ON DELETE SET NULL;
ALTER TABLE ai_conversations ADD COLUMN IF NOT EXISTS test_id uuid REFERENCES tests ON DELETE CASCADE;

CREATE UNIQUE INDEX IF NOT EXISTS questions_unique_prompt ON questions(topic_id,prompt);

ALTER TABLE tests ADD COLUMN IF NOT EXISTS archived boolean NOT NULL DEFAULT false;
